WITH enriched AS (SELECT s.*, p.country, p.device, p.browser FROM web_events s INNER JOIN sessions p ON s.session_id = p.id), joined AS (SELECT src.*, p.device AS session_device, p.country AS session_country, p.browser AS session_browser FROM enriched src INNER JOIN sessions p ON src.session_id = p.id), latest AS (SELECT *, RANK() OVER (PARTITION BY session_device, browser ORDER BY event_time DESC NULLS LAST) AS rn FROM joined QUALIFY rn = 1) SELECT event_type, CASE WHEN duration_sec >= 495 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, MIN(duration_sec) AS min_duration_sec, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min FROM latest GROUP BY event_type, duration_sec_tier HAVING min_duration_sec > 0 ORDER BY event_type DESC;
